<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {era5Api} from '@/api/era5'
import WindFieldCanvas from '@/components/WindFieldCanvas.vue'
const loading=ref(false),status=ref<any>({}),sources=ref<any>({items:[],state:{}}),plans=ref<any[]>([]),jobs=ref<any[]>([]),files=ref<any[]>([]),stats=ref<any>({}),audit=ref<any>({}),batches=ref<any[]>([]),batchPlan=ref<any>({}),perSplit=ref(12),tab=ref('analysis'),sampleOptions=ref<any[]>([]),selectedSampleId=ref(''),selectedStep=ref(3),displayMode=ref<'compare'|'single'>('compare'),fieldMode=ref<'speed'|'u'|'v'>('speed')
const labels=['t-18h','t-12h','t-6h','t'];const scale=computed(()=>stats.value.preview?.speed_range??[0,1])
async function load(){loading.value=true;try{[status.value,sources.value,files.value,stats.value,audit.value,sampleOptions.value]=await Promise.all([era5Api.status(),era5Api.sources(),era5Api.files(),era5Api.statistics(),era5Api.audit(),era5Api.samples({limit:200})]);[plans.value,jobs.value,batches.value,batchPlan.value]=await Promise.all([era5Api.plans(),era5Api.jobs(),era5Api.batches(),era5Api.scalePreview(perSplit.value)]);if(!selectedSampleId.value&&sampleOptions.value.length)selectedSampleId.value=sampleOptions.value[0].id;if(selectedSampleId.value)stats.value.preview=await era5Api.sample(selectedSampleId.value)}finally{loading.value=false}}
async function selectSample(){if(!selectedSampleId.value)return;loading.value=true;try{stats.value.preview=await era5Api.sample(selectedSampleId.value)}finally{loading.value=false}}
const visibleSteps=computed(()=>displayMode.value==='compare'?[0,1,2,3]:[selectedStep.value])
async function sourceAction(id:string,kind:'check'|'benchmark'){loading.value=true;try{kind==='check'?await era5Api.checkSource(id):await era5Api.benchmarkSource(id);ElMessage.success(kind==='check'?'数据源检查完成':'真实固定工作负载基准完成');await load()}catch(error:any){ElMessage.error(error.response?.data?.message||'数据源操作失败')}finally{loading.value=false}}
async function selectSource(id:string){try{await era5Api.setDefaultSource(id);ElMessage.success('默认数据源已更新');await load()}catch(error:any){ElMessage.error(error.response?.data?.message||'数据源不可用')}}
function sourceStatus(row:any){return row.last_result?.status==='available'?'可用':row.last_result?.status==='unauthorized'?'未授权':row.last_result?.status==='network_failed'?'网络失败':'未检查'}
function metric(value:any,suffix=''){return value==null?'未测得':`${Number(value).toFixed(2)}${suffix}`}
async function startBatch(){loading.value=true;try{await era5Api.createScaleBatch(perSplit.value);ElMessage.success('规模化真实 ERA5 批次已启动');await load();tab.value='batch'}catch(error:any){ElMessage.error(error.response?.data?.message||'批次创建失败')}finally{loading.value=false}}
async function stopBatch(row:any){await era5Api.cancelBatch(row.id);await load()}
async function resumeBatch(row:any){await era5Api.resumeBatch(row.id);ElMessage.success('批次已从断点恢复');await load()}
async function freeze(){try{const result=await era5Api.freeze();ElMessage.success(`数据集已冻结：${result.dataset_version}`)}catch(error:any){ElMessage.error(error.response?.data?.message||'质量门禁未通过') }}
async function test(){const value=await era5Api.test();ElMessage[value.reachable?'success':'warning'](value.message||'连接检查完成')}
async function publicSample(){loading.value=true;try{const result=await era5Api.publicSample();ElMessage.success(`真实 ERA5 已接入，新增 ${result.build.built} 个样本`);await load();tab.value='analysis'}catch(error:any){ElMessage.error(error.response?.data?.message||'公共 ERA5 下载失败')}finally{loading.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;loading.value=true;try{await era5Api.importFile(file);ElMessage.success('文件已校验并归档');await load()}catch(error:any){ElMessage.error(error.response?.data?.message||'导入失败')}finally{loading.value=false;input.value=''}}
async function build(){loading.value=true;try{const result=await era5Api.build();ElMessage.success(`新增 ${result.built} 个，跳过 ${result.skipped} 个`);await load();tab.value='analysis'}finally{loading.value=false}}
async function startJob(plan:any,row:any){try{await era5Api.createJob({request:row.request,typhoon_id:plan.typhoon_id,sid:plan.sid});ElMessage.success('小范围下载任务已创建');await load()}catch(error:any){ElMessage.error(error.response?.data?.message||'任务创建失败')}}
async function jobAction(job:any,kind:'cancel'|'retry'){kind==='cancel'?await era5Api.cancelJob(job.id):await era5Api.retryJob(job.id);await load()}
onMounted(load)
</script>
<template><div v-loading="loading" class="page-stack"><div class="page-heading"><div><h2>ERA5 近海面风场</h2><p>U10 / V10 · 历史台风中心裁剪 · 四时次时空样本</p></div><el-button @click="load">刷新状态</el-button></div>
<div class="status-grid"><div class="status-card"><span class="card-label">ERA5 数据</span><strong>{{status.connected?'已接入':status.configured?'CDS 已配置':'待接入'}}</strong><small>{{status.message}}</small></div><div class="status-card"><span class="card-label">ERA5 文件</span><strong class="stat-value">{{stats.era5_files??0}}</strong><small>通过质量检查的归档</small></div><div class="status-card"><span class="card-label">单时次风场</span><strong class="stat-value">{{stats.wind_fields??0}}</strong><small>2 × 31 × 31</small></div><div class="status-card"><span class="card-label">四时次样本</span><strong class="stat-value">{{stats.spatiotemporal_samples??0}}</strong><small>4 × 2 × 31 × 31</small></div></div>
<el-card class="data-card"><el-tabs v-model="tab">
<el-tab-pane label="数据源诊断" name="sources"><el-alert title="只展示实测与元数据估算" description="实际传输量和 HTTP 请求数无法可靠取得时显示“未测得”，不会以文件大小或理论分块数冒充。自动模式选择最近通过质量比对且冷读取更快的数据源。" type="info" :closable="false"/><div class="era-toolbar"><span>当前策略：<strong>{{sources.state?.default||'auto'}}</strong></span><el-button size="small" @click="selectSource('auto')">自动选择</el-button></div><el-table :data="sources.items" empty-text="暂无数据源状态"><el-table-column prop="name" label="数据源" min-width="210"/><el-table-column label="状态" width="100"><template #default="s">{{sourceStatus(s.row)}}</template></el-table-column><el-table-column label="布局 / 版本" min-width="180"><template #default="s">{{s.row.last_result?.layout||'—'}} · {{s.row.last_result?.dataset_version||'—'}}</template></el-table-column><el-table-column label="元数据" width="110"><template #default="s">{{metric(s.row.last_result?.metadata_seconds,' 秒')}}</template></el-table-column><el-table-column label="冷读取" width="110"><template #default="s">{{metric(sources.state?.benchmarks?.[s.row.id]?.cold_read_seconds,' 秒')}}</template></el-table-column><el-table-column label="传输 / 请求" width="150"><template #default="s">{{metric(sources.state?.benchmarks?.[s.row.id]?.actual_transfer_bytes)}} / {{metric(sources.state?.benchmarks?.[s.row.id]?.http_requests)}}</template></el-table-column><el-table-column label="操作" width="240"><template #default="s"><el-button link @click="sourceAction(s.row.id,'check')">检查</el-button><el-button link type="primary" :disabled="s.row.id==='ecmwf_arco'||s.row.last_result?.status!=='available'" @click="sourceAction(s.row.id,'benchmark')">真实基准</el-button><el-button link :disabled="s.row.id!=='google_arco'&&s.row.last_result?.status!=='available'" @click="selectSource(s.row.id)">设为默认</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="数据接入" name="access"><el-alert v-if="status.connected" title="真实 ERA5 风场已接入" type="success" :closable="false" show-icon><template #default>当前使用 ECMWF/Copernicus 生产、Google Cloud 公开托管的 ARCO-ERA5；CDS 个人令牌仍可用于扩展下载。</template></el-alert><el-alert v-else-if="!status.configured" title="可直接使用公共 ERA5" type="info" :closable="false" show-icon><template #default>公共 ARCO-ERA5 无需个人令牌；如需使用 CDS 官方 API 扩展下载，再配置 <code>.cdsapirc</code> 并接受许可。</template></el-alert><div class="era-toolbar"><el-button type="primary" @click="publicSample">接入公共 ERA5 样本</el-button><el-button @click="test">检查 CDS 连接</el-button><el-button tag="label">导入 NetCDF<input class="visually-hidden" type="file" accept=".nc,.nc4" @change="upload"></el-button><a :href="status.setup_url" target="_blank">CDS 配置说明</a><a :href="status.dataset_url" target="_blank">ERA5 数据集</a></div><p class="muted-note">仅下载 U10/V10 和台风轨迹附近的小范围数据；缓存预算 {{status.disk_budget_gb}} GB。所有文件必须通过字段、单位、坐标、时间、缺测和风速范围检查。</p>
<el-table :data="files" empty-text="尚无 ERA5 文件"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="original_filename" label="文件"/><el-table-column label="时间范围"><template #default="s">{{s.row.coverage.time_start}} 至 {{s.row.coverage.time_end}}</template></el-table-column><el-table-column label="有效率" width="100"><template #default="s">{{((s.row.quality_report.valid_ratio||0)*100).toFixed(2)}}%</template></el-table-column><el-table-column label="大小" width="110"><template #default="s">{{(s.row.file_size/1048576).toFixed(1)}} MB</template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="下载计划" name="plans"><p class="muted-note">计划来自第三阶段严格样本，并分别覆盖训练、验证、测试分区。每个时次以当时的历史台风中心为准，跨日界线时自动拆分。</p><el-collapse><el-collapse-item v-for="p in plans" :key="p.sid+p.forecast_time" :title="`${p.sid} · ${p.split} · 起报 ${p.forecast_time}`"><el-table :data="p.requests"><el-table-column prop="time" label="时次"/><el-table-column label="中心"><template #default="s">{{s.row.center.join(', ')}}</template></el-table-column><el-table-column label="范围 N/W/S/E"><template #default="s">{{s.row.request.area.join(' / ')}}</template></el-table-column><el-table-column prop="request_hash" label="请求指纹" show-overflow-tooltip/><el-table-column label="操作" width="100"><template #default="s"><el-button link type="primary" :disabled="!status.configured" @click="startJob(p,s.row)">下载</el-button></template></el-table-column></el-table></el-collapse-item></el-collapse><h3 class="section-gap">任务记录</h3><el-table :data="jobs" empty-text="尚无下载任务"><el-table-column prop="sid" label="SID"/><el-table-column prop="status" label="状态"/><el-table-column prop="phase" label="阶段"/><el-table-column label="进度"><template #default="s">{{s.row.progress==null?'CDS 暂无可信进度':s.row.progress+'%'}}</template></el-table-column><el-table-column prop="error_message" label="说明" show-overflow-tooltip/><el-table-column label="操作"><template #default="s"><el-button v-if="['queued','submitting','processing','downloading','validating'].includes(s.row.status)" link @click="jobAction(s.row,'cancel')">取消</el-button><el-button v-if="['failed','cancelled','interrupted'].includes(s.row.status)" link type="primary" @click="jobAction(s.row,'retry')">重试</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="批量准备" name="batch"><el-alert title="按独立台风事件优先扩充" description="目标为训练 50 条/20 事件、验证 20 条/5 事件、测试 20 条/5 事件；达到事件目标后才补相邻窗口。" type="info" :closable="false"/><div class="era-toolbar"><span>本批上限</span><el-input-number v-model="perSplit" :min="1" :max="12"/><el-button @click="load">预估</el-button><el-button type="primary" :disabled="audit.engineering_target_met" @click="startBatch">开始真实批次</el-button><span>本地约 {{((batchPlan.estimated_bytes||0)/1048576).toFixed(2)}} MB · 远程保守估算 {{((batchPlan.estimated_remote_bytes||0)/1073741824).toFixed(2)}} GiB · {{batchPlan.samples||0}} 条</span></div><el-table :data="batches"><el-table-column prop="id" label="批次" show-overflow-tooltip/><el-table-column prop="status" label="状态"/><el-table-column label="进度"><template #default="s">{{s.row.cursor||0}} / {{s.row.requested}}（成功 {{s.row.completed}}，失败 {{s.row.failed}}）</template></el-table-column><el-table-column label="缓存 / 请求"><template #default="s">{{s.row.cache_hits||0}} / {{s.row.metrics?.http_requests==null?'未测得':s.row.metrics.http_requests}}</template></el-table-column><el-table-column label="实际归档"><template #default="s">{{((s.row.actual_bytes||0)/1048576).toFixed(2)}} MB</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button v-if="['queued','running'].includes(s.row.status)" link type="danger" @click="stopBatch(s.row)">暂停</el-button><el-button v-if="['paused','failed','partial'].includes(s.row.status)&&(s.row.cursor||0)<s.row.requested" link type="primary" @click="resumeBatch(s.row)">恢复</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="风场分析" name="analysis"><div class="wind-toolbar"><el-select v-model="selectedSampleId" filterable placeholder="选择真实 ERA5 样本" @change="selectSample"><el-option v-for="sample in sampleOptions" :key="sample.id" :value="sample.id" :label="`${sample.sid} · ${sample.forecast_time} · ${sample.split}`"/></el-select><el-radio-group v-model="fieldMode"><el-radio-button value="speed">合成风速</el-radio-button><el-radio-button value="u">U10</el-radio-button><el-radio-button value="v">V10</el-radio-button></el-radio-group><el-radio-group v-model="displayMode"><el-radio-button value="compare">四时次对比</el-radio-button><el-radio-button value="single">单时次</el-radio-button></el-radio-group><el-select v-if="displayMode==='single'" v-model="selectedStep" style="width:120px"><el-option v-for="(label,index) in labels" :key="label" :label="label" :value="index"/></el-select></div><template v-if="stats.preview"><div class="sample-heading"><div><strong>{{stats.preview.sid}}</strong> · {{stats.preview.forecast_time}} → {{stats.preview.target_time}} · {{stats.preview.split}}</div><span>{{fieldMode==='speed'?`统一色标 ${scale[0].toFixed(1)}–${scale[1].toFixed(1)} m/s`:'分量单位 m/s'}}</span></div><div class="wind-grid" :class="{single:displayMode==='single'}"><article v-for="i in visibleSteps" :key="i"><h4>{{labels[i]}} · {{stats.preview.input_times?.[i]||''}}</h4><WindFieldCanvas :u="stats.preview.u[i]" :v="stats.preview.v[i]" :mode="fieldMode" :label="labels[i]+' 风场'" :scale-min="scale[0]" :scale-max="scale[1]"/><div class="wind-axis"><span>{{stats.preview.centers?.[i]?.latitude?.toFixed(2)}}°N</span><span>{{stats.preview.centers?.[i]?.longitude?.toFixed(2)}}°E</span></div></article></div><div class="sample-meta"><span>网格 {{stats.preview.shape?.join(' × ')}}</span><span>目标风速 {{stats.preview.target_wind?.toFixed(2)}} m/s</span><span>质量检查 {{stats.preview.finite?'通过':'异常'}}</span><span>处理版本 {{stats.preview.processing_version}}</span></div><p class="muted-note">合成风速模式同时绘制 U/V 风矢量；所有数据来自所选真实 ERA5 四时次样本，缺失时次不会自动填充。</p></template><el-empty v-else description="当前没有可用 ERA5 风场"/></el-tab-pane>
<el-tab-pane label="样本质量" name="samples"><div class="metric-grid"><div><span>v2 样本</span><strong>{{audit.samples??0}}</strong></div><div><span>独立事件</span><strong>{{audit.events??0}}</strong></div><div><span>训练集 样本/事件</span><strong>{{audit.splits?.train?.samples??0}} / {{audit.splits?.train?.events??0}}（还差 {{audit.remaining?.train?.samples??0}} / {{audit.remaining?.train?.events??0}}）</strong></div><div><span>验证集 样本/事件</span><strong>{{audit.splits?.validation?.samples??0}} / {{audit.splits?.validation?.events??0}}（还差 {{audit.remaining?.validation?.samples??0}} / {{audit.remaining?.validation?.events??0}}）</strong></div><div><span>测试集 样本/事件</span><strong>{{audit.splits?.test?.samples??0}} / {{audit.splits?.test?.events??0}}（还差 {{audit.remaining?.test?.samples??0}} / {{audit.remaining?.test?.events??0}}）</strong></div><div><span>正式门禁</span><strong>{{audit.formal_training_allowed?'通过':'未通过'}}</strong></div></div><div class="era-toolbar"><el-button :disabled="!stats.era5_files" @click="build">构建/补齐四时次样本</el-button><el-button type="primary" :disabled="!audit.passed" @click="freeze">冻结实验清单</el-button></div><p class="muted-note">复用第三阶段按年份划分，SID 不跨分区；标签固定为 t+6h，风场仅含 t-18h、t-12h、t-6h、t，不使用未来信息。重复执行通过版本、唯一键和 SHA-256 保证幂等。</p></el-tab-pane>
</el-tabs></el-card></div></template>
<style scoped>.era-toolbar,.wind-toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin:16px 0}.wind-toolbar>.el-select:first-child{width:min(460px,100%)}.era-toolbar a{font-size:13px}.status-card small{color:#748396;line-height:1.5}.wind-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.wind-grid.single{grid-template-columns:minmax(360px,620px);justify-content:center}.wind-grid article{border:1px solid #dde5ec;padding:12px;background:#f8fafb}.wind-grid h4{text-align:center;margin:0 0 8px;font-size:13px}.wind-axis,.sample-meta{display:flex;justify-content:space-between;color:#697b8d;font-size:11px;margin-top:7px}.sample-meta{justify-content:flex-start;gap:20px;padding:12px 0;border-bottom:1px solid #e1e7ed}.sample-heading{display:flex;justify-content:space-between;color:#647487;margin-bottom:12px}@media(max-width:1450px){.wind-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){.wind-grid{grid-template-columns:1fr}}</style>
